Dining Philosophers, Deadlock

sem_t left(int p) { return p; }

sem_t right(int p) { return (p + 1) % 5; }

void getforks(p) {
       sem_wait(forks[left(p)]);
       sem_wait(forks[right(p)]);

}

void putforks(p) {
       sem_post(forks[left(p)]);
       sem_post(forks[right(p)]);

}

A circular wait occurs if each philosopher picks up the fork
to the left and then waits to pick up the fork to the right

Dining Philosophers, No Deadlock

sem_t left(int p) { return p; }

sem_t right(int p) { return (p + 1) % 5; }

void getforks(p) {                        If philosopher 4 picks up
       if (p == 4) {                      the fork to the right first ,
              sem_wait(forks[right(p)]);  no circular wait occurs as
              sem_wait(forks[left(p)]);   each philosopher requests
       } else {                           forks in the same order
              sem_wait(forks[left(p)]);
              sem_wait(forks[right(p)]);
       }

}

void putforks(p) {
       sem_post(forks[left(p)]);
       sem_post(forks[right(p)]);

}
